"""Render docs/APP_INDICATORS.md from app_risk specs (single source of truth).

    .venv/Scripts/python.exe scripts/render_indicator_docs.py
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from app_risk import config as C  # noqa: E402
from app_risk.data import SQL  # noqa: E402
from app_risk.indicators import CLAIM_SPEC, DISCLAIMER, PROVIDER_SPEC  # noqa: E402


def main() -> None:
    L = [f"# Application-native risk indicators (`{C.INDICATOR_SET_KEY}` v{C.INDICATOR_SET_VERSION})", "",
         "_Generated by `scripts/render_indicator_docs.py` from `app_risk/`. Edit the code, not this file._", "",
         f"> {DISCLAIMER}", "",
         "## Data used (read-only, column-whitelisted)", "",
         "| Query | SQL |", "|---|---|"]
    L += [f"| {k} | `{v}` |" for k, v in SQL.items()]
    L += ["", f"Never loaded or used: {', '.join(f'`{c}`' for c in sorted(C.FORBIDDEN_COLUMNS))} "
          "(post-review decisions would leak the outcome; patient personal or sensitive fields are not needed). "
          "The loader rejects data containing them, and the MySQL session is read-only.", "",
          "## Two timelines (claim level)", "",
          "1. **Knowledge:** the claims visible in one consistent, read-only database snapshot taken at assessment time "
          "(`START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY`). Nothing outside the snapshot is used.",
          "2. **Service date:** within the snapshot, comparisons use `CLAIM_DATE` only:",
          "   - prior-history indicators use snapshot claims dated **on or before** the assessed claim's date, excluding the claim itself;",
          f"   - duplicate detection uses snapshot claims within **±{C.DUPLICATE_WINDOW_DAYS} calendar days**.",
          "",
          "**`CLAIM_ID` never determines order or history.** It only identifies claims and excludes the assessed claim. Results do not "
          "depend on the order in which claims were entered (tested over all insertion orders).", "",
          "| Property | Behaviour |", "|---|---|",
          f"| Claims dated more than {C.DUPLICATE_WINDOW_DAYS} days after the assessed claim | never change its result |",
          "| A back-dated claim entered later | updates the assessments of the later-dated claims it precedes (new knowledge); earlier snapshots are kept |",
          "| Same snapshot | same result, same digest |", "",
          "Indicator set 1.0.0 used \"`CLAIM_ID` < assessed claim\" as history and missed claims entered out of date order. It was never deployed; 2.0.0 replaces it.", "",
          "## Snapshots, digest and audit trail", "",
          "Each claim assessment carries `snapshot_claim_count` (claims visible in the snapshot), `prior_history_claim_count`, "
          "`comparison_claim_ids` on every indicator (exactly which claims were compared), `indicator_set_version`, `assessed_at` "
          "(added by the service) and `indicators_digest`: SHA-256 of the canonical JSON of the deterministic content "
          "(claim, indicator set and version, status, rule hits, all indicator results including comparison IDs, triggered count, "
          "priority and reasons).", "",
          "`assessed_at`, the snapshot counts and the disclaimer are provenance, **not** part of the digest. A claim added anywhere "
          "else would otherwise create a new snapshot for every claim, while any change that matters to this claim already "
          "changes its indicator values or comparison IDs.", "",
          "**Append-only:** a new snapshot is stored only when its digest differs from the claim's latest **non-failed** snapshot "
          "(`CLAIM_LATEST_VALID_ASSESSMENT`). Snapshots are never updated or deleted (database triggers).", "",
          "## Training-data rule (Track 3)", "",
          "Future supervised training must take each outcome's features from the snapshot that **existed when the investigator "
          "recorded the outcome**: the linked snapshot if it was assessed at or before the decision, otherwise the latest non-failed "
          "snapshot before the decision (database view `OUTCOME_TRAINING_SNAPSHOT`; `app_risk.snapshots.select_training_snapshot`). "
          "Historical training features must **never** be recomputed with information entered later.", "",
          "## Provider level", "",
          "Claims with `CLAIM_DATE` ≤ the as-of date, compared with peers at the same cutoff (date-based; independent of `CLAIM_ID`).", "",
          "Dates are calendar dates from MySQL (`DATE`), not converted through any timezone (tested under IST).", "",
          "## Claim-level indicators", "",
          "| Code | Name | Inputs | Calculation | Why | Triggered when |", "|---|---|---|---|---|---|"]
    L += [f"| `{k}` | {v[0]} | {v[1]} | {v[2]} | {v[3]} | {v[4]} |" for k, v in CLAIM_SPEC.items()]
    L += ["", "Statuses: `ok`; `insufficient_history` (not enough earlier data, so `triggered` is null); "
          "`not_applicable` (e.g. no previous claim). Insufficient history is never filled with a default.", "",
          "### Review priority (ordering aid, not a score or a decision)", "",
          "- **High:** any existing SQL rule hit on the claim, or ≥ 2 triggered indicators",
          "- **Elevated:** exactly 1 triggered indicator",
          "- **Routine:** otherwise", "",
          "Reasons are always listed. Priority never changes `CLAIM.STATUS` and never approves or rejects a claim.", "",
          "## Provider-level indicators", "",
          f"Ratio indicators need ≥ {C.MIN_PROVIDER_CLAIMS} claims. Peer comparison needs ≥ {C.MIN_PEERS} other providers with ≥ "
          f"{C.MIN_PROVIDER_CLAIMS} claims; \"unusually high\" means above the peers' {C.PEER_HIGH_PERCENTILE}th percentile, and "
          f"\"unusually low\" below their {C.PEER_LOW_PERCENTILE}th.", "",
          "| Code | Name | Calculation | Peer comparison |", "|---|---|---|---|"]
    L += [f"| `{k}` | {v[0]} | {v[1]} | {({'high': 'flag if unusually high', 'low': 'flag if unusually low'}).get(v[2], 'informational')} |"
          for k, v in PROVIDER_SPEC.items()]
    L += ["", "Provider-level and claim-level results are reported separately and never combined into one number.", "",
          "## Configured thresholds", "", "| Setting | Value |", "|---|---|"]
    L += [f"| `{k}` | {getattr(C, k)} |" for k in dir(C) if k.isupper() and k not in ("FORBIDDEN_COLUMNS", "INDICATOR_SET_KEY", "INDICATOR_SET_VERSION")]
    L += ["", "Thresholds are design choices, not learned values: the application has no labelled outcomes yet. "
          "Changing any of them requires a new indicator-set version.", ""]
    out = ROOT / "docs" / "APP_INDICATORS.md"
    out.write_text("\n".join(L), encoding="utf-8")
    print(f"Wrote {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
